-- Replace product branding in persisted agent text only; leave other configuration fields and historical messages untouched.
UPDATE custom_agents SET config = jsonb_set(config, '{system_prompt}', to_jsonb(replace(config->>'system_prompt', 'WeKnora', '环枢'))) WHERE jsonb_typeof(config->'system_prompt') = 'string' AND config->>'system_prompt' LIKE '%WeKnora%';
UPDATE custom_agents SET config = jsonb_set(config, '{context_template}', to_jsonb(replace(config->>'context_template', 'WeKnora', '环枢'))) WHERE jsonb_typeof(config->'context_template') = 'string' AND config->>'context_template' LIKE '%WeKnora%';
UPDATE custom_agents SET config = jsonb_set(config, '{rewrite_prompt_system}', to_jsonb(replace(config->>'rewrite_prompt_system', 'WeKnora', '环枢'))) WHERE jsonb_typeof(config->'rewrite_prompt_system') = 'string' AND config->>'rewrite_prompt_system' LIKE '%WeKnora%';
UPDATE custom_agents SET config = jsonb_set(config, '{rewrite_prompt_user}', to_jsonb(replace(config->>'rewrite_prompt_user', 'WeKnora', '环枢'))) WHERE jsonb_typeof(config->'rewrite_prompt_user') = 'string' AND config->>'rewrite_prompt_user' LIKE '%WeKnora%';
UPDATE custom_agents SET config = jsonb_set(config, '{fallback_prompt}', to_jsonb(replace(config->>'fallback_prompt', 'WeKnora', '环枢'))) WHERE jsonb_typeof(config->'fallback_prompt') = 'string' AND config->>'fallback_prompt' LIKE '%WeKnora%';
UPDATE custom_agents SET config = jsonb_set(config, '{intent_prompts}', (SELECT jsonb_object_agg(key, replace(value, 'WeKnora', '环枢')) FROM jsonb_each_text(config->'intent_prompts'))) WHERE jsonb_typeof(config->'intent_prompts') = 'object' AND (config->'intent_prompts')::text LIKE '%WeKnora%';
UPDATE custom_agents SET name = replace(name, 'WeKnora', '环枢'), description = replace(description, 'WeKnora', '环枢') WHERE name LIKE '%WeKnora%' OR description LIKE '%WeKnora%';
